use super::*;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabaseLimits,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding,export_sqlite_database,import_sqlite_database}};
fn fixture()->(serde_json::Value,EquationSnapshot){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let child=|index:usize|{let row=&f["children"][index];let target=&row["target"];let dialect=&target["dialect"];store::os_io::ArtifactRef{artifact_id:target["artifactId"].as_str().unwrap().into(),dialect:store::os_io::ArtifactDialect{artifact_kind:dialect["artifactKind"].as_str().unwrap().into(),standard:dialect["standard"].as_str().unwrap().into(),subset:dialect["subset"].as_str().unwrap().into()}}};let n=|kind|EquationNode{label:EquationNodeLabel(f["labelMaximum"].as_str().unwrap().parse().unwrap()),kind};let value=EquationSnapshot{notation:store::ArtifactChild::new(f["children"][0]["childId"].as_str().unwrap().into(),child(0)),results:store::ArtifactChild::new(f["children"][1]["childId"].as_str().unwrap().into(),child(1)),computed:store::ArtifactChild::new(f["children"][2]["childId"].as_str().unwrap().into(),child(2)),equation:EquationExprSnapshot{next_label:f["nextLabel"].as_str().unwrap().parse().unwrap(),expr:n(EquationNodeKind::Add{terms:vec![n(EquationNodeKind::Integer{lexeme:f["lexeme"].as_str().unwrap().into()}),n(EquationNodeKind::Rational{numer:f["numerator"].as_str().unwrap().into(),denom:f["denominator"].as_str().unwrap().into()}),n(EquationNodeKind::Symbol{name:f["symbol"].as_str().unwrap().into()}),n(EquationNodeKind::Mul{factors:vec![]}),n(EquationNodeKind::Pow{base:Box::new(n(EquationNodeKind::Add{terms:vec![]})),exponent:Box::new(n(EquationNodeKind::Mul{factors:vec![n(EquationNodeKind::Integer{lexeme:"1".into()})]}))})]})}};(f,value)}
#[test]
fn sqlite_snapshot_equation_typed_lexemes_labels_handles_and_independent_sql_edit(){use std::{io::Write,process::{Command,Stdio}};let(_,value)=fixture();let limits=SqliteDatabaseLimits::default();let database=value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(EquationSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),value);let bytes=export_sqlite_database(&database,limits,&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(d.query('SELECT COUNT(DISTINCT kind) AS n FROM equation_node').get().n!==6)throw Error('variants');const w=d.query('SELECT label_high,label_low FROM equation_node LIMIT 1').get();if(w.label_high!==4294967295||w.label_low!==4294967295)throw Error('u64 words');d.query('UPDATE equation_symbol SET name=?').run('edited independent SQL 世界');await Bun.write(Bun.stdout,d.serialize());d.close();";let mut p=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();p.stdin.take().unwrap().write_all(&bytes).unwrap();let output=p.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let restored=EquationSnapshot::from_sqlite_database(&import_sqlite_database(&output.stdout,limits,&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(restored.notation,value.notation);match restored.equation.expr.kind{EquationNodeKind::Add{terms}=>assert_eq!(terms[2].kind,EquationNodeKind::Symbol{name:"edited independent SQL 世界".into()}),_=>panic!("root differs")}}
#[test]
fn sqlite_snapshot_equation_actual_erased_binary_text_retain_only_persisted_state(){use store::os_io::{ArtifactDialect,IoPayload};let(_,value)=fixture();let limits=SqliteDatabaseLimits::default();let codec=crate::io::io().native.codec;let provider=codec.snapshot_sqlite.as_ref().unwrap();let dialect=ArtifactDialect{artifact_kind:"s.mathematical.equation".into(),standard:"1".into(),subset:"*".into()};let expected=value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>IoPayload::Binary(store::ArtifactPack::encode_pack(&value)),SnapshotEncoding::Text=>IoPayload::Text(store::ArtifactDsl::print_dsl(&value))};let database=(provider.export)(&codec.schema,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;assert_eq!(database,expected);let restored=(provider.import)(&codec.schema,&dialect,database,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;let restored=match restored{IoPayload::Binary(bytes)=><EquationSnapshot as store::ArtifactPack>::decode_pack(&bytes).unwrap(),IoPayload::Text(text)=><EquationSnapshot as store::ArtifactDsl>::parse_dsl(&text).unwrap()};assert_eq!(restored,value);}}
#[test]
fn sqlite_snapshot_equation_deep_retirement_exact_profile_and_bounded_cancellation(){let(f,mut value)=fixture();let limits=SqliteDatabaseLimits::default();let database=value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();for raw in f["invalidDialects"].as_array().unwrap(){let(kind,rest)=raw.as_str().unwrap().split_once('@').unwrap();let(standard,subset)=rest.split_once('/').unwrap();let dialect=store::os_io::ArtifactDialect{artifact_kind:kind.into(),standard:standard.into(),subset:subset.into()};assert!(value.validate_sqlite_snapshot_subset(&dialect,&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());}let mut node=EquationNode{label:EquationNodeLabel(0),kind:EquationNodeKind::Integer{lexeme:"deep".into()}};let depth=f["deep"].as_u64().unwrap()as usize;for index in 0..depth{node=EquationNode{label:EquationNodeLabel(index as u64),kind:EquationNodeKind::Add{terms:vec![node]}};}value.equation.expr=node;let database=value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let restored=EquationSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let mut node=&restored.equation.expr;let mut count=0;while let EquationNodeKind::Add{terms}=&node.kind{count+=1;node=&terms[0];}assert_eq!(count,depth);for limits in[SqliteDatabaseLimits{max_rows:f["maxRows"].as_u64().unwrap()as usize,..limits},SqliteDatabaseLimits{max_value_bytes:f["maxValueBytes"].as_u64().unwrap()as usize,..limits}]{assert!(value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(EquationSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());}let cancel=f["cancelAt"].as_u64().unwrap()as usize;let mut seen=false;let mut callback=|progress:store::sqlite_snapshot::SqliteSnapshotProgress|{if progress.phase==SqliteSnapshotPhase::ReconstructSnapshot&&progress.completed>=cancel{seen=true;false}else{true}};assert!(EquationSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut callback,limits)).is_err());assert!(seen);EquationSnapshot::retire_sqlite_snapshot(value);EquationSnapshot::retire_sqlite_snapshot(restored);}

#[test]
fn sqlite_snapshot_equation_authored_logical_grammar_demo_and_actual_declaration_agree(){
 let(_,value)=fixture();let codec=crate::io::io().native.codec;assert!(codec.snapshot_sqlite.is_some());assert_eq!(codec.pack_schema_hash,store::schema_hash(&<EquationSnapshot as store::ArtifactPack>::record_spec().unwrap()));
 let grammar=dsl::grammar::parse_grammar(include_str!("../../../../🚪️io/📸️snapshot/📝️text/📖️.grammar.semio")).unwrap();let recognizer=dsl::grammar::Recognizer::compile(&grammar);let text=store::ArtifactDsl::print_dsl(&value);assert!(recognizer.recognize(&text).unwrap(),"{text}");let demo=include_str!("../../../../🖼️assets/🎬️demo/🗣️.dsl.semio");let decoded=<EquationSnapshot as store::ArtifactDsl>::parse_dsl(demo).unwrap();assert!(recognizer.recognize(demo).unwrap());assert_eq!(store::ArtifactDsl::print_dsl(&decoded),demo);
 for invalid in[text.replace("mathematical.equation.dsl","stdio.json.dsl"),text.replace("mathematical.equation.dsl v1","mathematical.equation.dsl v2"),format!("{text}\nunowned-field=1")]{assert!(<EquationSnapshot as store::ArtifactDsl>::parse_dsl(&invalid).is_err());}
}
#[test]
fn sqlite_snapshot_equation_deep_erased_native_retains_flat_owned_state_on_small_stack(){
 let(f,value)=fixture();let depth=f["deep"].as_u64().unwrap()as usize;
 std::thread::Builder::new().stack_size(256*1024).spawn(move||{
  let mut value=value;let mut node=EquationNode{label:EquationNodeLabel(u64::MAX),kind:EquationNodeKind::Symbol{name:"leaf\0世界".into()}};for _ in 0..depth{node=EquationNode{label:EquationNodeLabel(u64::MAX),kind:EquationNodeKind::Mul{factors:vec![node]}}}EquationSnapshot::retire_sqlite_snapshot(EquationSnapshot{notation:value.notation.clone(),results:value.results.clone(),computed:value.computed.clone(),equation:EquationExprSnapshot{expr:std::mem::replace(&mut value.equation.expr,node),next_label:0}});
  let limits=SqliteDatabaseLimits::default();let expected=value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let provider=crate::io::io().native.codec.snapshot_sqlite.unwrap();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.mathematical.equation".into(),standard:"1".into(),subset:"*".into()};
  for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=(provider.import)(crate::MATH_DOCUMENT_SCHEMA,&dialect,expected.clone(),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;assert_eq!((provider.export)(crate::MATH_DOCUMENT_SCHEMA,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value,expected);}
  EquationSnapshot::retire_sqlite_snapshot(value);
 }).unwrap().join().unwrap();
}

#[test]
fn sqlite_snapshot_equation_controlled_typed_construction_preserves_admission_and_known_work(){
 let(f,value)=fixture();let text=store::ArtifactDsl::print_dsl(&value);let(_,body)=store::semio_format::split_text_preamble(&text).unwrap();let spec=<EquationSnapshot as store::ArtifactPack>::record_spec().unwrap();let record=dsl::parse_exact(body,&spec,&dsl::ParseOptions{limits:dsl::Limits::default(),mode:dsl::SourceMode::Document}).unwrap();let bind=crate::standards::v1::subsets::any::io::snapshot::binary::reconstruct_pack_record_controlled;
 let mut callback=|_:protocol::native_decoding::NativeDecodeProgress|true;let mut control=dsl::NativeDecodeControl::new(1024*1024,&mut callback);let restored=bind(&record,&mut control,1_000_000).unwrap();assert_eq!(restored,value);EquationSnapshot::retire_sqlite_snapshot(restored);
 let mut control=dsl::NativeDecodeControl::new(1024*1024,&mut callback);assert!(bind(&record,&mut control,f["maxRows"].as_u64().unwrap()as usize).is_err());assert_eq!(control.owned_bytes(),0,"row admission must precede typed field copying");
 let mut control=dsl::NativeDecodeControl::new(f["maxValueBytes"].as_u64().unwrap()as usize,&mut callback);assert!(bind(&record,&mut control,1_000_000).is_err());
 EquationSnapshot::retire_sqlite_snapshot(value);
}

#[test]
fn sqlite_snapshot_equation_whole_native_control_preserves_typed_fields_and_interior_cancellation(){let(_,mut value)=fixture();let mut node=EquationNode{label:EquationNodeLabel(u64::MAX),kind:EquationNodeKind::Integer{lexeme:"noncanonical arbitrary String 世界".repeat(4096)}};for _ in 0..600{node=EquationNode{label:EquationNodeLabel(u64::MAX),kind:EquationNodeKind::Add{terms:vec![node]}}}let old=std::mem::replace(&mut value.equation.expr,node);let retired=EquationSnapshot{notation:value.notation.clone(),results:value.results.clone(),computed:value.computed.clone(),equation:EquationExprSnapshot{expr:old,next_label:0}};EquationSnapshot::retire_sqlite_snapshot(retired);let limits=SqliteDatabaseLimits::default();let expected=value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();for payload in[store::os_io::IoPayload::Text(store::ArtifactDsl::print_dsl(&value)),store::os_io::IoPayload::Binary(store::ArtifactPack::encode_pack(&value))]{let restored=EquationSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(restored.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),expected);EquationSnapshot::retire_sqlite_snapshot(restored);for limits in[SqliteDatabaseLimits{max_rows:10,..limits},SqliteDatabaseLimits{max_value_bytes:4096,..limits}]{assert!(EquationSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());}let mut interior=false;let mut progress=|event:store::sqlite_snapshot::SqliteSnapshotProgress|{if event.phase==SqliteSnapshotPhase::DecodeNative&&event.completed>=256&&event.completed<event.total{interior=true;false}else{true}};assert!(EquationSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut progress,limits)).is_err());assert!(interior);}EquationSnapshot::retire_sqlite_snapshot(value);}
